'use strict';
(()=>{
 const panel=$('trend'),toolbar=document.createElement('div');toolbar.className='chart-navigation';const caption=document.createElement('span');caption.className='chart-window-caption';let drag=null;
 function draw(){if(current)chart(current);}
 function zoom(op){const n=assetViewport.points.length;if(!n)return;const [a,b]=assetViewport.window||[0,n-1],size=op==='all'?n:Math.max(2,Math.min(n,Math.round((b-a+1)*(op==='in'?.6:1.7)))),start=Math.max(0,Math.min(n-size,Math.round((a+b-size)/2)));assetViewport.window=[start,Math.min(n-1,start+size-1)];draw();}
 for(const [op,label]of [['in','＋ 放大'],['out','− 缩小'],['all','显示全部']]){const b=document.createElement('button');b.type='button';b.className='outline';b.textContent=label;b.onclick=()=>zoom(op);toolbar.append(b);}toolbar.append(caption);$('assetChart').before(toolbar);
 const sliders=document.createElement('div');sliders.className='chart-window';for(const title of ['起点','终点']){const l=document.createElement('label'),i=document.createElement('input');l.textContent=title;i.type='range';i.step=1;i.min=0;i.setAttribute('aria-label','资产曲线'+title);l.append(i);sliders.append(l);}$('assetChart').after(sliders);const axis=FamilyChartAxis.attach(panel,'家庭资产',draw);const [start,end]=sliders.querySelectorAll('input');start.oninput=()=>{assetViewport.window=[Math.min(+start.value,+end.value),+end.value];draw();};end.oninput=()=>{assetViewport.window=[+start.value,Math.max(+start.value,+end.value)];draw();};
 window.FamilyAssetNavigation={scale:values=>axis.scale(values),reset:()=>axis.reset(),update(){const pts=assetViewport.points,n=pts.length,[a,b]=assetViewport.window||[0,Math.max(0,n-1)];for(const s of [start,end]){s.max=Math.max(0,n-1);s.disabled=n<2;}start.value=a;end.value=b;caption.textContent=n?pts[a]?.date+' — '+pts[b]?.date+' · '+(b-a+1)+'/'+n+' 个记录点':'暂无资产记录';}};
 $('assetChart').addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();zoom(e.deltaY<0?'in':'out');}},{passive:false});$('assetChart').addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=assetViewport.points.length,[a,b]=assetViewport.window||[0,n-1];drag={x:e.clientX,a,size:b-a+1,width:$('assetChart').clientWidth};});window.addEventListener('pointermove',e=>{if(!drag||Math.abs(drag.x-e.clientX)<8)return;const from=Math.max(0,Math.min(assetViewport.points.length-drag.size,drag.a+Math.round((drag.x-e.clientX)/drag.width*drag.size)));assetViewport.window=[from,from+drag.size-1];draw();});window.addEventListener('pointerup',()=>drag=null);window.addEventListener('pointercancel',()=>drag=null);
 const tooltip=document.createElement('div');tooltip.className='income-tooltip';tooltip.hidden=true;$('assetChart').style.position='relative';$('assetChart').addEventListener('pointermove',e=>{if(drag||e.target.tagName!=='circle')return;const title=e.target.querySelector('title');if(title){tooltip.textContent=title.textContent;tooltip.hidden=false;$('assetChart').append(tooltip);}});$('assetChart').addEventListener('click',e=>{const title=e.target.tagName==='circle'?e.target.querySelector('title'):null;if(title){tooltip.textContent=title.textContent;tooltip.hidden=false;$('assetChart').append(tooltip);}});$('assetChart').addEventListener('pointerleave',()=>tooltip.hidden=true);$('assetChart').before(panel.querySelector('.y-axis-controls'));if(current)draw();
})();
